package ru.neverland.runtime;
import java.io.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;
import ru.neverland.townyresearch.licenses.*;
/** Runs against the already built artifact; no server or production data is opened. */
public final class LicenseJournalBoundaries{
 static int checks;static void check(boolean ok,String message){if(!ok)throw new AssertionError(message);checks++;}static void close(LicenseRepository r)throws Exception{r.closeAsync().toCompletableFuture().get(5,TimeUnit.SECONDS);}
 public static void main(String[] args)throws Exception{
  Path folder=Files.createTempDirectory("license-boundaries");UUID actor=UUID.randomUUID(),seller=UUID.randomUUID();var terms=new TechLicense.Terms(UUID.randomUUID(),seller,UUID.randomUUID(),actor,"irrigation",2,.15,12500,60);var row=TechLicense.offered(terms,60,1234).by(LicenseActor.player(actor,"OriginalMayor",seller)).auditAck();Path good=folder.resolve("licenses.yml");var repo=new LicenseRepository(good);repo.load();repo.commit(repo.rows(),Map.of(terms.id(),row)).toCompletableFuture().get(5,TimeUnit.SECONDS);close(repo);var restored=new LicenseRepository(good);restored.load();var actual=restored.rows().get(terms.id());check(actual.actor().equals(row.actor())&&actual.changedAt()==row.changedAt(),"decision identity, town and exact timestamp survive disk round trip");close(restored);
  Path large=folder.resolve("too-large.yml");try(var out=new RandomAccessFile(large.toFile(),"rw")){out.setLength(LicenseRepository.MAX_BYTES+1);}var capped=new LicenseRepository(large);try{capped.load();throw new AssertionError("oversize accepted");}catch(IOException expected){check(expected.getMessage().contains("размер"),"byte cap rejects before malformed YAML is parsed");}close(capped);check(Files.size(large)==LicenseRepository.MAX_BYTES+1,"rejected oversized bytes are unchanged after close");
  Path many=folder.resolve("too-many.yml");var text=new StringBuilder("schema: 1\nlicenses:\n");for(int i=0;i<TechLicense.MAX_RECORDS+1;i++)text.append("  ").append(UUID.randomUUID()).append(": {}\n");Files.writeString(many,text);var archive=new LicenseRepository(many);try{archive.load();throw new AssertionError("row cap accepted");}catch(IOException expected){check(expected.getMessage().contains("Слишком много"),"archive cap rejects before parsing incomplete row payloads");}close(archive);check(Files.readString(many).contentEquals(text),"rejected archive is preserved");
  Path invalid=folder.resolve("invalid-actor.yml");String bad=Files.readString(good).replace("name: OriginalMayor","name: "+"x".repeat(129));Files.writeString(invalid,bad);var actorRepo=new LicenseRepository(invalid);try{actorRepo.load();throw new AssertionError("oversize actor accepted");}catch(IllegalArgumentException expected){check(true,"unbounded actor payload is rejected before publication");}close(actorRepo);check(Files.readString(invalid).equals(bad),"unread actor payload is never overwritten");
  System.out.println("LicenseJournalBoundaries PASS "+checks+" checks");
 }
}
